%Generated by ChatGPT

function fullpic = quadrantLayout(p1, p2, p3, p4, w, bgColor)

    % Get the actual screen dimensions
    screenRect = Screen('Rect', w);
    screenW = RectWidth(screenRect);
    screenH = RectHeight(screenRect);

    % Define the four destination quadrants
    halfW = floor(screenW / 2);
    halfH = floor(screenH / 2);

    quadrant1 = [0,     0,     halfW, halfH];
    quadrant2 = [halfW, 0,     screenW, halfH];
    quadrant3 = [0,     halfH, halfW, screenH];
    quadrant4 = [halfW, halfH, screenW, screenH];

    % Create a temporary offscreen window
    layoutWin = Screen('OpenOffscreenWindow', w, bgColor, screenRect);

    % Convert the four image matrices into textures
    tex1 = Screen('MakeTexture', w, p1);
    tex2 = Screen('MakeTexture', w, p2);
    tex3 = Screen('MakeTexture', w, p3);
    tex4 = Screen('MakeTexture', w, p4);

    % Draw each image into its own quadrant
    Screen('DrawTexture', layoutWin, tex1, [], quadrant1);
    Screen('DrawTexture', layoutWin, tex2, [], quadrant2);
    Screen('DrawTexture', layoutWin, tex3, [], quadrant3);
    Screen('DrawTexture', layoutWin, tex4, [], quadrant4);

    % Return the complete image matrix
    fullpic = Screen('GetImage', layoutWin);

    % Release resources
    Screen('Close', [tex1, tex2, tex3, tex4]);
    Screen('Close', layoutWin);

end
